21:/// Resolve the target capability from the owning schema. No capability string
22:/// is copied into this compatibility module.
23:pub fn target_capability(target_method: &str) -> Result<String> {
24:    let schema = super::threetched::sealed_schema("tched_router")?;
25:    let declaration = schema.methods.get(target_method).ok_or_else(|| {
26:        anyhow!("tched_router schema does not declare target method '{target_method}'")
27:    })?;
28:    Ok(schema
