34:fn decode<T: serde::de::DeserializeOwned>(args: &Value, method: &str) -> Result<T> {
35:    serde_json::from_value(args.clone())
36:        .with_context(|| format!("invalid large_language_model.{method} arguments"))
37:}
38:
39:/// Validate a compatibility call and identify the exact canonical tched_router
40:/// operation and capability it requires.
41:///
42:/// The caller MUST run target-method admission against the same pinned
43:/// tched_router PluginSchema and verified identity before invoking this plan.
44:/// Possession of the outer large_language_model capability is not sufficient.
45:pub fn plan_method(method: &str, args: &Value) -> Result<TargetPlan> {
46:    let (target_method, target_args) = match method {
47:        "stream_generate" => {
48:            let input: super::tched_router::generation::StartGenerationInput =
49:                decode(args, method)?;
50:            input.validate()?;
51:            ("start_generation", serde_json::to_value(input)?)
52:        }
53:        other => return Err(anyhow!("unknown large_language_model method: {other}")),
54:    };
55:    Ok(TargetPlan {
56:        plugin_id: TARGET_PLUGIN_ID,
57:        method: target_method,
58:        required_capability: target_capability(target_method)?,
59:        args: target_args,
60:    })
61:}
