65:pub fn complete_method(method: &str, target_result: Value) -> Result<Value> {
66:    match method {
67:        "stream_generate" => Ok(serde_json::to_value(
68:            serde_json::from_value::<super::tched_router::generation::GenerationMutationOutput>(
69:                target_result,
70:            )
71:            .context("tched_router generation returned an invalid receipt")?,
72:        )?),
73:        other => Err(anyhow!("unknown large_language_model method: {other}")),
74:    }
